// Package idgen creates UUIDv7 values and the type-prefixed public IDs that
// ZSoftly Core exposes on its API.
package idgen

import (
	"crypto/rand"
	"database/sql/driver"
	"encoding/hex"
	"errors"
	"fmt"
	"sync"
	"time"
)

// UUID is a 128-bit RFC 9562 UUID. The zero value is the nil UUID.
type UUID [16]byte

// Nil is the all-zero UUID.
var Nil UUID

var (
	v7mu      sync.Mutex
	v7lastMs  int64
	v7counter uint16
	clock     = func() time.Time { return time.Now() }
)

// NewV7 returns a time-ordered UUIDv7. IDs generated by one process are
// strictly increasing: within one millisecond a 12-bit counter in rand_a
// increases, and on counter overflow the timestamp advances by one
// millisecond.
func NewV7() (UUID, error) {
	var u UUID
	if _, err := rand.Read(u[6:]); err != nil {
		return Nil, fmt.Errorf("read random bytes: %w", err)
	}

	v7mu.Lock()
	ms := clock().UnixMilli()
	if ms > v7lastMs {
		v7lastMs = ms
		// Seed the counter in the lower half of its range so that many IDs in
		// the same millisecond do not immediately overflow.
		v7counter = (uint16(u[6])<<8 | uint16(u[7])) & 0x07ff
	} else {
		v7counter++
		if v7counter > 0x0fff {
			v7lastMs++
			v7counter = 0
		}
	}
	ms = v7lastMs
	counter := v7counter
	v7mu.Unlock()

	u[0] = byte(ms >> 40)
	u[1] = byte(ms >> 32)
	u[2] = byte(ms >> 24)
	u[3] = byte(ms >> 16)
	u[4] = byte(ms >> 8)
	u[5] = byte(ms)
	u[6] = 0x70 | byte(counter>>8)
	u[7] = byte(counter)
	u[8] = 0x80 | (u[8] & 0x3f)
	return u, nil
}

// MustNewV7 is NewV7 for callers that cannot handle a failing system random
// source. It panics on failure.
func MustNewV7() UUID {
	u, err := NewV7()
	if err != nil {
		panic(err)
	}
	return u
}

// Version returns the UUID version nibble.
func (u UUID) Version() int { return int(u[6] >> 4) }

// IsNil reports whether u is the nil UUID.
func (u UUID) IsNil() bool { return u == Nil }

// Time returns the millisecond timestamp of a UUIDv7. It returns the zero
// time for other versions.
func (u UUID) Time() time.Time {
	if u.Version() != 7 {
		return time.Time{}
	}
	ms := int64(u[0])<<40 | int64(u[1])<<32 | int64(u[2])<<24 | int64(u[3])<<16 | int64(u[4])<<8 | int64(u[5])
	return time.UnixMilli(ms).UTC()
}

// String returns the canonical 8-4-4-4-12 lowercase hex form.
func (u UUID) String() string {
	var buf [36]byte
	hex.Encode(buf[0:8], u[0:4])
	buf[8] = '-'
	hex.Encode(buf[9:13], u[4:6])
	buf[13] = '-'
	hex.Encode(buf[14:18], u[6:8])
	buf[18] = '-'
	hex.Encode(buf[19:23], u[8:10])
	buf[23] = '-'
	hex.Encode(buf[24:], u[10:])
	return string(buf[:])
}

var errInvalidUUID = errors.New("invalid uuid")

// ParseUUID parses the canonical 36-character form.
func ParseUUID(s string) (UUID, error) {
	var u UUID
	if len(s) != 36 || s[8] != '-' || s[13] != '-' || s[18] != '-' || s[23] != '-' {
		return Nil, errInvalidUUID
	}
	compact := s[0:8] + s[9:13] + s[14:18] + s[19:23] + s[24:]
	if _, err := hex.Decode(u[:], []byte(compact)); err != nil {
		return Nil, errInvalidUUID
	}
	return u, nil
}

// MarshalText implements encoding.TextMarshaler.
func (u UUID) MarshalText() ([]byte, error) { return []byte(u.String()), nil }

// UnmarshalText implements encoding.TextUnmarshaler.
func (u *UUID) UnmarshalText(text []byte) error {
	parsed, err := ParseUUID(string(text))
	if err != nil {
		return err
	}
	*u = parsed
	return nil
}

// Value implements database/sql/driver.Valuer so a UUID binds to a Postgres
// uuid column.
func (u UUID) Value() (driver.Value, error) { return u.String(), nil }

// Scan implements database/sql.Scanner for Postgres uuid columns.
func (u *UUID) Scan(src any) error {
	switch v := src.(type) {
	case string:
		return u.UnmarshalText([]byte(v))
	case []byte:
		if len(v) == 16 {
			copy(u[:], v)
			return nil
		}
		return u.UnmarshalText(v)
	case [16]byte:
		*u = v
		return nil
	default:
		return fmt.Errorf("scan uuid: unsupported source type %T", src)
	}
}
